using System;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class TrafficPursuitTests
    {
        static TrafficOptions C()=>TrafficOptions.Defaults();
        static TrafficPursuitOptions P()=>TrafficPursuitOptions.Defaults();
        static TrafficFrame F()=>new TrafficFrame{Car=true,Belt=true,Helmet=true,Lights=true,Engine=1000,Street="Unknown",Speed=10};
        static WalletData W(){var w=new WalletData{Bank=10000,Cash=777};TrafficTransactions.Configure(w,true,()=>{},out _);TrafficTransactions.Preferences(w,true,true,()=>{},out _);return w;}
        static TrafficTicket Ticket()=>new TrafficTicket{Id="case",Plate="RPTEST",Street="Alta St",Model=123,LimitMph=50,Pursuit=P(),Lines=new System.Collections.Generic.List<TrafficLine>{new TrafficLine{Code=TrafficOffence.NoSeatbelt,Amount=150}}};
        static WalletData Begun(){var w=W();Assert.True(TrafficTransactions.Begin(w,Ticket(),()=>{},out _));return w;}
        [Fact] public void OldNumericOffencesAndOldPreferencesStayCompatible(){Assert.Equal(0,(int)TrafficOffence.Speeding);Assert.Equal(6,(int)TrafficOffence.BurstTyre);var w=JsonConvert.DeserializeObject<WalletData>("{\"Bank\":500,\"Traffic\":{\"Enabled\":true,\"Future\":42}}");Assert.True(w.Traffic.Valid);Assert.False(w.Traffic.AdvancedOffences);Assert.False(w.Traffic.PursuitEnabled);Assert.Equal(42,(int)w.Traffic.Extra["Future"]);}
        [Theory] [InlineData(TrafficOffence.MobilePhone,100)] [InlineData(TrafficOffence.Tailgating,120)] [InlineData(TrafficOffence.AimingWeapon,350)] [InlineData(TrafficOffence.ExcessiveHorn,125)]
        public void FourAdditionalOffencesRequireOptInAndHaveReferencePrices(TrafficOffence code,int price){var f=F();f.MobilePhone=code==TrafficOffence.MobilePhone;f.Tailgating=code==TrafficOffence.Tailgating;f.AimingWeapon=code==TrafficOffence.AimingWeapon;f.HornMilliseconds=code==TrafficOffence.ExcessiveHorn?10000:0;Assert.Empty(TrafficRules.Evaluate(f,C()));var line=Assert.Single(TrafficRules.Evaluate(f,C(),true));Assert.Equal(code,line.Code);Assert.Equal(price,line.Amount);Assert.True(line.Valid);}
        [Theory] [InlineData(0,false)] [InlineData(9999,false)] [InlineData(10000,true)] [InlineData(60000,true)] [InlineData(60001,false)]
        public void HornThresholdAndEvidenceBounds(int ms,bool expected){var f=F();f.HornMilliseconds=ms;Assert.Equal(expected,TrafficRules.Evaluate(f,C(),true).Any(l=>l.Code==TrafficOffence.ExcessiveHorn));}
        [Fact] public void HornHoldResetsOnReleaseVehicleChangePauseOrLongStall(){var m=new TrafficBehaviourMeter();m.Observe(1,true,0,true);for(int i=0;i<10;i++)m.Observe(1,true,1000,true);Assert.Equal(10000,m.HornMilliseconds);m.Observe(1,false,16,true);Assert.Equal(0,m.HornMilliseconds);m.Observe(1,true,0,true);m.Observe(1,true,1000,true);m.Observe(2,true,1000,true);Assert.Equal(0,m.HornMilliseconds);m.Observe(2,true,1000,true);m.Observe(2,true,16,false);Assert.Equal(0,m.HornMilliseconds);m.Observe(2,true,0,true);m.Observe(2,true,1001,true);Assert.Equal(0,m.HornMilliseconds);}
        [Theory] [InlineData(10,5,1,0,true)] [InlineData(10,10,1,0,true)] [InlineData(10,10.1f,1,0,false)] [InlineData(10,5,-1,0,false)] [InlineData(10,5,.64f,0,false)] [InlineData(10,5,1,3,false)] [InlineData(1,5,1,0,false)] [InlineData(float.NaN,5,1,0,false)]
        public void HeadwayNeedsMovementShortRangeSameDirectionAndSameLevel(float speed,float distance,float alignment,float height,bool expected){Assert.Equal(expected,TrafficPursuitRules.Tailgate(speed,distance,alignment,height));}
        [Fact] public void AllElevenLedgerCodesSerializeWithoutDiscardingOlderCodes(){var t=Ticket();t.Lines=Enum.GetValues(typeof(TrafficOffence)).Cast<TrafficOffence>().Select(c=>new TrafficLine{Code=c,Value=c==TrafficOffence.ExcessiveHorn?10000:c==TrafficOffence.Speeding?1:0,Amount=TrafficRules.Cost(c,c==TrafficOffence.Speeding?1:0)}).ToList();Assert.Equal(11,t.Lines.Count);Assert.True(t.Valid);var w=W();Assert.True(TrafficTransactions.Begin(w,t,()=>{},out _));w=JsonConvert.DeserializeObject<WalletData>(JsonConvert.SerializeObject(w));Assert.True(w.Traffic.Valid);Assert.Equal(11,w.Traffic.Tickets[0].Lines.Count);Assert.Equal(1490,w.Traffic.Tickets[0].Total);}
        [Fact] public void MovingFugitiveTimesVehicleAndFootSeparatelyAndStopsWaiting(){var p=P();var clock=new TrafficPursuitClock();for(int i=0;i<34;i++)Assert.False(clock.Advance(1000,true,p));for(int i=0;i<100;i++)Assert.False(clock.Advance(1000,false,p));Assert.Equal(34000,clock.VehicleElapsed);Assert.False(clock.Advance(5000,true,p));Assert.True(clock.Advance(1000,true,p));clock.EnterFoot();for(int i=0;i<44;i++)Assert.False(clock.Advance(1000,true,p));Assert.True(clock.Advance(1000,true,p));Assert.Equal(45000,clock.FootElapsed);Assert.Equal(35000,clock.VehicleElapsed);}
        [Theory] [InlineData(0,5,3,3)] [InlineData(0,2,3,2)] [InlineData(0,0,3,0)] [InlineData(1,5,3,0)] [InlineData(4,5,3,0)] [InlineData(0,5,4,0)] [InlineData(0,6,3,0)]
        public void BackupNeverLowersExistingStarsOrOverridesGlobalDisabledPolice(int current,int max,int request,int expected){Assert.Equal(expected,TrafficPursuitRules.BackupLevel(current,max,request));}
        [Fact] public void ReferIsDurableOnceAndNeverDebitsFineOrWallet(){var w=Begun();int saves=0;Assert.True(TrafficTransactions.Refer(w,"case",3,()=>saves++,out bool changed));Assert.True(changed);Assert.Null(w.Traffic.Pending);Assert.Equal("evaded",w.Traffic.Tickets[0].Outcome);Assert.Equal(3,w.Traffic.Tickets[0].BackupLevel);Assert.Equal(10000,w.Bank);Assert.Equal(777,w.Cash);Assert.False(w.Traffic.Tickets[0].Paid);w=JsonConvert.DeserializeObject<WalletData>(JsonConvert.SerializeObject(w));Assert.True(TrafficTransactions.Refer(w,"case",3,()=>throw new Exception(),out changed));Assert.False(changed);Assert.False(TrafficTransactions.Refer(w,"case",2,()=>throw new Exception(),out _));Assert.Equal(1,saves);Assert.True(TrafficTransactions.Pay(w,"case",()=>{},out _));Assert.Equal(9850,w.Bank);}
        [Fact] public void FailedReferralRollsBackAndAllowsRetry(){var w=Begun();string before=JsonConvert.SerializeObject(w);Assert.Throws<InvalidOperationException>(()=>TrafficTransactions.Refer(w,"case",3,()=>throw new InvalidOperationException(),out _));Assert.Equal(before,JsonConvert.SerializeObject(w));Assert.True(TrafficTransactions.Refer(w,"case",3,()=>{},out _));}
        [Fact] public void InterruptedReloadOrServedStopCannotBecomeBackupRequest(){foreach(string outcome in new[]{"interrupted","served","evaded"}){var w=Begun();TrafficTransactions.Finish(w,"case",outcome,()=>{},out _);Assert.False(TrafficTransactions.Refer(w,"case",3,()=>throw new Exception(),out _));Assert.Equal(0,w.Traffic.Tickets[0].BackupLevel);}}
        [Fact] public void LegacyStopCannotEscalateAndPreferencesCannotChangeDuringApproach(){var w=W();w.Traffic.PursuitEnabled=false;var t=Ticket();t.Pursuit=null;TrafficTransactions.Begin(w,t,()=>{},out _);Assert.False(TrafficTransactions.Refer(w,"case",3,()=>throw new Exception(),out _));Assert.False(TrafficTransactions.Preferences(w,true,true,()=>throw new Exception(),out _));Assert.False(w.Traffic.PursuitEnabled);}
        [Fact] public void DisabledOrInvalidRecordCannotRefer(){var w=Begun();w.Traffic.Enabled=false;Assert.False(TrafficTransactions.Refer(w,"case",3,()=>throw new Exception(),out _));w=Begun();w.Traffic.Tickets[0].Pursuit.BackupStars=0;Assert.False(w.Traffic.Valid);Assert.False(TrafficTransactions.Refer(w,"case",3,()=>throw new Exception(),out _));}
        [Fact] public void SnapshotAndUnknownMetadataSurviveReferralAndPayment(){var w=Begun();var j=JObject.FromObject(w);j["FutureWallet"]=7;j["Traffic"]["Tickets"][0]["Pursuit"]["FuturePlan"]="keep";w=j.ToObject<WalletData>();TrafficTransactions.Refer(w,"case",3,()=>{},out _);TrafficTransactions.Pay(w,"case",()=>{},out _);Assert.Equal(7,(int)w.Extra["FutureWallet"]);Assert.Equal("keep",(string)w.Traffic.Tickets[0].Pursuit.Extra["FuturePlan"]);Assert.Equal(35,w.Traffic.Tickets[0].Pursuit.VehicleSeconds);}
        [Fact] public void BackupMetadataCannotForgeOpenServedOrPlanlessRecords(){var t=Ticket();t.BackupLevel=3;Assert.False(t.Valid);t.Outcome="evaded";Assert.True(t.Valid);t.Pursuit=null;Assert.False(t.Valid);t.Pursuit=P();t.BackupLevel=4;Assert.False(t.Valid);}
        [Theory] [InlineData(true,true,0,2,true)] [InlineData(true,false,0,2,false)] [InlineData(true,true,.5f,2,false)] [InlineData(true,true,0,3,false)] [InlineData(false,true,0,2,false)]
        public void FootConferenceRequiresUnarmedStationaryPlayerAndProximity(bool foot,bool unarmed,float speed,float distance,bool expected){Assert.Equal(expected,TrafficPursuitRules.FootInspection(foot,unarmed,speed,distance));}
        [Fact] public void PreferenceSaveFailurePreservesExistingInvoiceAndMetadata(){var w=W();string before=JsonConvert.SerializeObject(w);Assert.Throws<Exception>(()=>TrafficTransactions.Preferences(w,false,false,()=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(w));}
    }
}
